// Step 2: Smart Cadence & Cancellation Evaluator
const body = $input.first().json.body || $input.first().json;

const recipientEmail = (body.recipient_email || body.email || '').trim().toLowerCase();
const currentStep = Number(body.current_step || 0);
const hasReplied = Boolean(body.has_replied || body.replied);
const isUnsubscribed = Boolean(body.is_unsubscribed || body.unsubscribed);
const lastSentAt = body.last_sent_at ? new Date(body.last_sent_at) : null;

if (!recipientEmail) {
  throw new Error('Validation failed: "recipient_email" parameter is required.');
}

// Cancellation Circuit Breaker: If lead replied or unsubscribed, CANCEL immediately
if (hasReplied || isUnsubscribed) {
  return [{
    json: {
      status: 'CANCELLED',
      recipient_email: recipientEmail,
      reason: hasReplied ? 'Inbound reply already received.' : 'Recipient requested unsubscription.',
      next_step: null,
      should_send: false,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// Non-negotiable Agency OS Cadence Rule: Max 2 Follow-Ups (3 touches total)
const MAX_FOLLOWUPS = 2;
if (currentStep >= MAX_FOLLOWUPS) {
  return [{
    json: {
      status: 'SEQUENCE_COMPLETED',
      recipient_email: recipientEmail,
      reason: 'Maximum sequence touches reached (2 follow-ups).',
      next_step: null,
      should_send: false,
      evaluated_at: new Date().toISOString()
    }
  }];
}

// Calculate delay: Step 1 = 3 business days, Step 2 = 4 business days
const delayBusinessDays = currentStep === 0 ? 3 : 4;
const nextStepNumber = currentStep + 1;

return [{
  json: {
    status: 'SCHEDULED',
    recipient_email: recipientEmail,
    next_step: nextStepNumber,
    delay_business_days: delayBusinessDays,
    template_key: `followup_step_${nextStepNumber}`,
    should_send: true,
    scheduled_at: new Date().toISOString()
  }
}];
